$('#semester_id').change(function (e) { 
    let semester_id = $(this).val(); 
     console.log(123456789);
    read(semester_id); 
totalMarks(semester_id);
});

function read(semester_id) {
    $("#subject_reslut_re tbody").html(''); 

    let sendingData = {
        "semester_id": semester_id, 
        "action": "report_result"
    };
    console.log("Sending Data: ", sendingData);

    $.ajax({
        method: "POST",
        dataType: "JSON",
        url: "../api/view.php", 
        data: sendingData,
        success: function(data) {
            let status = data.status;
            let response = data.data;
            let tr = '';

            if (status) {
                response.forEach(itm => {
                    tr += "<tr>";
                    for (let i in itm) {
                        tr += `<td>${itm[i]}</td>`;
                    }
                   
                });


                $("#subject_reslut_re tbody").append(tr);
            } else {
                console.log("Error:", response);
            }
        },
        error: function(data) {
            console.error("AJAX Error:",response.data);
        }
    });
}




   function totalMarks(semester_id){

   

    let form_data = {
    
     
        "semester_id": semester_id, 
        "action": "Total" 
    };

    $.ajax({
        method: "POST",
        dataType: "JSON",
      
        url: "../api/view.php", 
        data: form_data,
        success: function (data) {
            if (data.status) {
                let response = data.data;
                let totalMarks = response.Total;
                let percentage = response.Percentage;
                let grade = response.Grade;

                //   dynamic waaye 
                $(".result_total").html(`
                    <h2>Total: ${totalMarks}</h2>
                    <h2>Percentage: ${percentage}%</h2>
                    <h2>Grade: ${grade}</h2>
                `);
            } else {
                console.error("Error: ", data.data);
                $(".result_total").html("<h2>Error retrieving data.</h2>");
            }
        },
        error: function (error) {
            console.error("AJAX Error: ", error);
        }
    });
   }


